function reverseString(string $text): string
{
    $reversed = '';
    for ($i = strlen($text) - 1; $i >= 0; $i--) {
        $reversed .= $text[$i];
    }
    return $reversed;
}

echo reverseString('INTERVIEW');   // WEIVRETNI

// Two-pointer version (in place on an array of characters)
function reverseInPlace(string $text): string
{
    $chars = str_split($text);
    for ($left = 0, $right = count($chars) - 1; $left < $right; $left++, $right--) {
        [$chars[$left], $chars[$right]] = [$chars[$right], $chars[$left]];
    }
    return implode('', $chars);
}

function countChars(string $text): array
{
    $counts = [];
    foreach (str_split($text) as $char) {
        $counts[$char] = ($counts[$char] ?? 0) + 1;
    }
    return $counts;
}

foreach (countChars('INTERVIEW') as $char => $count) {
    echo "{$char} → {$count}\n";
}

