function duplicateChars(string $text): array
{
    $counts = [];
    foreach (str_split($text) as $char) {
        $counts[$char] = ($counts[$char] ?? 0) + 1;
    }

    $duplicates = [];
    foreach ($counts as $char => $count) {
        if ($count > 1) {
            $duplicates[] = $char;
        }
    }
    return $duplicates;
}

echo implode(', ', duplicateChars('programming'));   // r, g, m

function isPalindrome(string $text): bool
{
    $clean = preg_replace('/[^a-z0-9]/', '', strtolower($text));

    $left = 0;
    $right = strlen($clean) - 1;

    while ($left < $right) {
        if ($clean[$left] !== $clean[$right]) {
            return false;
        }
        $left++;
        $right--;
    }
    return true;
}

var_dump(isPalindrome('A man, a plan, a canal: Panama'));  // true
var_dump(isPalindrome('Laravel'));                         // false

function isAnagram(string $a, string $b): bool
{
    $a = str_replace(' ', '', strtolower($a));
    $b = str_replace(' ', '', strtolower($b));

    if (strlen($a) !== strlen($b)) {
        return false;
    }

    $counts = [];
    foreach (str_split($a) as $char) {
        $counts[$char] = ($counts[$char] ?? 0) + 1;
    }

    foreach (str_split($b) as $char) {
        if (empty($counts[$char])) {
            return false;          // missing, or already used up
        }
        $counts[$char]--;
    }
    return true;
}

var_dump(isAnagram('Listen', 'Silent'));   // true
var_dump(isAnagram('hello', 'world'));     // false

// Sorting version
function isAnagramSorted(string $a, string $b): bool
{
    $sort = function (string $s): string {
        $chars = str_split(str_replace(' ', '', strtolower($s)));
        sort($chars);
        return implode('', $chars);
    };
    return $sort($a) === $sort($b);
}

function countVowelsAndConsonants(string $text): array
{
    $vowels = 0;
    $consonants = 0;

    foreach (str_split(strtolower($text)) as $char) {
        if (in_array($char, ['a', 'e', 'i', 'o', 'u'], true)) {
            $vowels++;
        } elseif ($char >= 'a' && $char <= 'z') {
            $consonants++;
        }
    }

    return ['vowels' => $vowels, 'consonants' => $consonants];
}

$result = countVowelsAndConsonants('Hello World');
echo "Vowels: {$result['vowels']}, Consonants: {$result['consonants']}";
// Vowels: 3, Consonants: 7

function firstUniqueChar(string $text): ?string
{
    $counts = [];
    foreach (str_split($text) as $char) {
        $counts[$char] = ($counts[$char] ?? 0) + 1;
    }

    foreach (str_split($text) as $char) {
        if ($counts[$char] === 1) {
            return $char;
        }
    }
    return null;
}

var_dump(firstUniqueChar('swiss'));    // "w"
var_dump(firstUniqueChar('aabb'));     // NULL

function reverseWords(string $sentence): string
{
    $words = preg_split('/\s+/', trim($sentence));

    $reversed = [];
    for ($i = count($words) - 1; $i >= 0; $i--) {
        $reversed[] = $words[$i];
    }

    return implode(' ', $reversed);
}

echo reverseWords('Laravel is a PHP framework');   // framework PHP a is Laravel

