function reverseArray(array $items): array
{
    $left = 0;
    $right = count($items) - 1;

    while ($left < $right) {
        $temp = $items[$left];
        $items[$left] = $items[$right];
        $items[$right] = $temp;

        $left++;
        $right--;
    }
    return $items;
}

print_r(reverseArray([1, 2, 3, 4, 5]));   // [5, 4, 3, 2, 1]

function maxAndMin(array $numbers): array
{
    if ($numbers === []) {
        throw new InvalidArgumentException('The array is empty.');
    }

    $max = $min = $numbers[0];

    foreach ($numbers as $n) {
        if ($n > $max) {
            $max = $n;
        }
        if ($n < $min) {
            $min = $n;
        }
    }
    return ['max' => $max, 'min' => $min];
}

$result = maxAndMin([12, 45, 7, 89, 23]);
echo "Max: {$result['max']}, Min: {$result['min']}";   // Max: 89, Min: 7

function secondLargest(array $numbers): ?int
{
    $first = null;
    $second = null;

    foreach ($numbers as $n) {
        if ($first === null || $n > $first) {
            $second = $first;
            $first = $n;
        } elseif ($n < $first && ($second === null || $n > $second)) {
            $second = $n;
        }
    }
    return $second;
}

var_dump(secondLargest([10, 5, 20, 20, 8]));   // int(10)
var_dump(secondLargest([7, 7, 7]));            // NULL

function findDuplicates(array $numbers): array
{
    $seen = [];
    $duplicates = [];

    foreach ($numbers as $n) {
        if (isset($seen[$n])) {
            $duplicates[$n] = true;
        } else {
            $seen[$n] = true;
        }
    }
    return array_keys($duplicates);
}

print_r(findDuplicates([4, 2, 7, 2, 4, 9, 4]));   // [2, 4]

function removeDuplicates(array $items): array
{
    $seen = [];
    $result = [];

    foreach ($items as $item) {
        if (! isset($seen[$item])) {
            $seen[$item] = true;
            $result[] = $item;
        }
    }
    return $result;
}

print_r(removeDuplicates([3, 5, 3, 8, 5, 1]));   // [3, 5, 8, 1]

function missingNumber(array $numbers): int
{
    $n = count($numbers) + 1;
    $expected = intdiv($n * ($n + 1), 2);

    $actual = 0;
    foreach ($numbers as $number) {
        $actual += $number;
    }
    return $expected - $actual;
}

echo missingNumber([1, 2, 4, 5, 6]);   // 3

// XOR version: no risk of overflow
function missingNumberXor(array $numbers): int
{
    $xor = 0;
    $n = count($numbers) + 1;
    for ($i = 1; $i <= $n; $i++) {
        $xor ^= $i;
    }
    foreach ($numbers as $number) {
        $xor ^= $number;
    }
    return $xor;
}

function twoSum(array $numbers, int $target): ?array
{
    $seen = [];   // value => index

    foreach ($numbers as $i => $x) {
        $need = $target - $x;
        if (isset($seen[$need])) {
            return [$seen[$need], $i];
        }
        $seen[$x] = $i;
    }
    return null;
}

print_r(twoSum([2, 7, 11, 15], 9));   // [0, 1]
print_r(twoSum([3, 2, 4], 6));        // [1, 2]

function flatten(array $items): array
{
    $result = [];

    foreach ($items as $item) {
        if (is_array($item)) {
            foreach (flatten($item) as $value) {
                $result[] = $value;
            }
        } else {
            $result[] = $item;
        }
    }
    return $result;
}

