function fibonacci(int $n): array
{
    $series = [];
    $a = 0;
    $b = 1;

    for ($i = 0; $i < $n; $i++) {
        $series[] = $a;
        [$a, $b] = [$b, $a + $b];
    }
    return $series;
}

