// Recursive nth Fibonacci with memoisation
function fib(int $n, array &$memo = []): int
{
    if ($n < 2) {
        return $n;
    }
    return $memo[$n] ??= fib($n - 1, $memo) + fib($n - 2, $memo);
}

echo fib(50);   // 12586269025

function isPrime(int $n): bool
{
    if ($n < 2) {
        return false;
    }
    if ($n % 2 === 0) {
        return $n === 2;
    }
    for ($i = 3; $i * $i <= $n; $i += 2) {
        if ($n % $i === 0) {
            return false;
        }
    }
    return true;
}

