function factorial(int $n): int
{
    if ($n < 0) {
        throw new InvalidArgumentException('Factorial is not defined for negative numbers.');
    }

    $result = 1;
    for ($i = 2; $i <= $n; $i++) {
        $result *= $i;
    }
    return $result;
}

function factorialRecursive(int $n): int
{
    return $n <= 1 ? 1 : $n * factorialRecursive($n - 1);
}

echo factorial(5);            // 120
echo factorialRecursive(5);   // 120
echo factorial(0);            // 1

function fizzBuzz(int $n): array
{
    $out = [];
    for ($i = 1; $i <= $n; $i++) {
        $word = '';
        if ($i % 3 === 0) {
            $word .= 'Fizz';
        }
        if ($i % 5 === 0) {
            $word .= 'Buzz';
        }
        $out[] = $word !== '' ? $word : (string) $i;
    }
    return $out;
}

