function bubbleSort(array $items): array
{
    $n = count($items);

    for ($i = 0; $i < $n - 1; $i++) {
        $swapped = false;

        for ($j = 0; $j < $n - 1 - $i; $j++) {
            if ($items[$j] > $items[$j + 1]) {
                [$items[$j], $items[$j + 1]] = [$items[$j + 1], $items[$j]];
                $swapped = true;
            }
        }

        if (! $swapped) {
            break;   // already sorted
        }
    }
    return $items;
}

print_r(bubbleSort([5, 2, 9, 1, 5, 6]));   // [1, 2, 5, 5, 6, 9]

function binarySearch(array $numbers, int $target): int
{
    $low = 0;
    $high = count($numbers) - 1;

    while ($low <= $high) {
        $mid = $low + intdiv($high - $low, 2);

        if ($numbers[$mid] === $target) {
            return $mid;
        }
        if ($numbers[$mid] < $target) {
            $low = $mid + 1;
        } else {
            $high = $mid - 1;
        }
    }
    return -1;
}

echo binarySearch([1, 3, 5, 7, 9, 11, 13], 9);   // 4
echo binarySearch([1, 3, 5, 7, 9, 11, 13], 4);   // -1

function summariseByCustomer(array $orders): array
{
    $summary = [];

    foreach ($orders as $order) {
        $name = $order['customer'];
        $summary[$name] ??= ['orders' => 0, 'total' => 0];
        $summary[$name]['orders']++;
        $summary[$name]['total'] += $order['total'];
    }

    uasort($summary, fn ($a, $b) => $b['total'] <=> $a['total']);

    return $summary;
}

$orders = [
    ['customer' => 'Asha', 'total' => 500],
    ['customer' => 'Ravi', 'total' => 300],
    ['customer' => 'Asha', 'total' => 250],
];

foreach (summariseByCustomer($orders) as $name => $row) {
    echo "{$name}: {$row['orders']} " . ($row['orders'] === 1 ? 'order' : 'orders') . ", {$row['total']}\n";
}
// Asha: 2 orders, 750
// Ravi: 1 order, 300

function isBalanced(string $text): bool
{
    $pairs = [')' => '(', ']' => '[', '}' => '{'];
    $stack = [];

    foreach (str_split($text) as $char) {
        if (in_array($char, $pairs, true)) {          // opening bracket
            $stack[] = $char;
        } elseif (isset($pairs[$char])) {             // closing bracket
            if (array_pop($stack) !== $pairs[$char]) {
                return false;
            }
        }
    }
    return $stack === [];
}

var_dump(isBalanced('{[()]}'));   // true
var_dump(isBalanced('([)]'));     // false
var_dump(isBalanced('(('));       // false
